"""Record source precision evidence without inventing a noise bound."""
import collections,json,pathlib
from stage0_cohort import R,D,O,load,save
B=R/'MFM_p_data_information'
def main():
 fields=load(B/'configs/p_data_information/fields.json')['fields'];protocol=load(D/'workflows/wp5/configs/protocol.json');panels=load(O/'panel.json');pairs=load(O/'pairs.json');byid=collections.defaultdict(list)
 for p in pairs['TRAIN']['conformer']:byid[p['molecule_id']].append(p)
 selected=[]
 for r in panels['TRAIN']:
  if not r['core']:continue
  candidates=[p for p in byid[r['molecule_id']] if p['heavy_rmsd'] is not None and p['heavy_rmsd']>0 and not p['exact_stored_geometry']]
  if candidates:selected.append(max(candidates,key=lambda p:(p['heavy_rmsd'],-p['a'],-p['b'])))
  if len(selected)==4:break
 task_config={t['name']:t for t in protocol['tasks']}
 resolution=[]
 for f in fields:
  name=f['field_key'];task=name.split('.')[1];is_mopac=task.startswith('pm7');resolution.append(dict(field=name,unit=f['unit'],storage=dict(dtype='IEEE754 binary32',rounding='round-to-nearest unless source conversion explicitly states otherwise',unit_roundoff=2**-24,absolute_bound=None,reason='Without matched preconversion value, half-ulp is representation resolution only; raw printing and computation errors are separate'),historical_conversion=dict(dtype_authority='original WP5/typed float64',source_exact_pair_values=None,reason='Registered original Parquet metadata and owner catalog are available; no per-record physical-row locator in the inspected owner catalog; broad source-value scans forbidden'),printing_resolution=None,calculation_precision=None,method_accuracy=None,evidence_level='ONLY_CONTAINER_RESOLUTION; SOURCE_PRINT_AND_SCF_UNRESOLVED',expected_software_version=protocol['expected_versions']['mopac' if is_mopac else 'xtb'],original_task_configuration=task_config.get(task)))
 save(B/'results/p_data_information/resolution.json',dict(fields=resolution,existing_interface_evidence=dict(xtb_native_frame30='30 actual old calls/5 molecules; q0 rotation5/5; q0 quadrupole translation4/5; q+1 translation1/5; not a universal SCF or method-accuracy bound',r674='remains excluded',historical_192='UNKNOWN preserved'),source_locator_evidence=dict(canonical_records_columns=['record_ordinal','record_id','molecule_id','attempt_id','job_id','task_id','lane','total_atoms','new_role'],raw_example_row_groups=1607,raw_example_rows=205630,reason='Example raw footer spans broad record-ID/molecule ranges; no full table numeric search or new source index was started'),calibration_2B=dict(status='TRIGGERED_UNRESOLVED_INPUT_LINEAGE',candidates=selected,calls=0,max_calls=32,reason='Exact original task input geometry and per-record program/state/version lineage not recovered by registered point locators. Replacing original input by rounded pilot coordinates would change geometry; not allowed. This is unresolved, not NOT_TRIGGERED.',pm7_supported_setting=dict(parameter='SCFCRT',original_default=1e-4,tight=1e-5,source='https://openmopac.net/Manual/scf_test.html',original_keywords=task_config['pm7_B']['keywords']),xtb_setting=None,xtb_reason='No independently recovered 10x SCF-only setting for this actual original version/input; --acc is not silently substituted')))
 (B/'docs/p_data_information/02_NUMERICAL_RESOLUTION.md').write_text('''# 阶段2：数值分辨率与等价对照\n\n状态：COMPLETE_WITH_UNRESOLVED_SOURCE_PRECISION。\n\n109字段分别登记了容器、历史转换、打印、SCF/重复计算与方法准确性。pilot MFM4为FP32；原WP5/typed为F64权威。F64容器不等于源计算有64位有效精度；FP32可分的两个数也不能自动解释为可靠的化学差异。没有给字段任意设置统一化学显著阈值。\n\n既有native_frame30在5个分子上的30次真实xTB计算，仅支持原适用范围的参考系结论，不是全域SCF噪声上界。q0偶极旋转/平移5/5；中性四极平移4/5、q+1为1/5。r674保持关闭，历史192个坐标独立输出UNKNOWN不改写。未重复旋转套件或旧QM试点。\n\n已检查原WP5注册Parquet的存在、schema与footer，以及现有canonical.sqlite/typed catalog结构。owner索引有record_id和任务所有者，没有源物理行定位；例示源base_geometry的1607行组/205630记录具有宽record-ID范围。没有把缺少定点定位转成全表标签扫描或新全源索引。后续数值最早可追溯层明确为pilot MFM4，WP5→pilot差值保留暂不可判断。\n\n2B已触发评估：关键能量缺适用计算精度证据。候选只从冻结TRAIN核心按原顺序取前4个有真实差异的分子，每个取冻结配对中重原子RMSD最大的一对，清单见resolution.json。实际调用0：原任务的精确输入几何和逐记录版本/状态链未由现有定点定位恢复；不能将FP32 pilot坐标当作原程序精确输入开展对照。MOPAC原关键词及预期23.0.3已找到，SCFCRT默认1e-4与收紧1e-5的参数依据来自[官方SCF说明](https://openmopac.net/Manual/scf_test.html)；仅参数可恢复不代表整组输入可执行。xTB未把--acc改动冒充单独10倍SCF收敛设置。状态为TRIGGERED_UNRESOLVED_INPUT_LINEAGE，不是未触发，也没有启动空实验。\n\n因此阶段3报告原单位/固定D4幅度与真实覆盖，并明确区分存储层描述和计算可靠性未知。精度未知不阻断其余分析；32案例校准即使以后有结果，也不能提供全域确定误差界。\n''')
 p=load(B/'results/p_data_information/progress.json');p.update(stage2='COMPLETE_WITH_UNRESOLVED_SOURCE_PRECISION',stage2B='TRIGGERED_UNRESOLVED_INPUT_LINEAGE');save(B/'results/p_data_information/progress.json',p)
 print('RESOLUTION_REGISTERED',len(fields),len(selected),flush=True)
if __name__=='__main__':main()
